solution.javascript:
function productExceptSelf(nums) {
  const n = nums.length;
  const result = new Array(n);
  result[0] = 1;
  for (let i = 1; i < n; i++) result[i] = result[i - 1] * nums[i - 1];
  let suffix = 1;
  for (let i = n - 1; i >= 0; i--) {
    result[i] *= suffix;
    suffix *= nums[i];
  }
  return result;
}

